insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('jos-7-24','jos','여호수아',7,24,'여호수아가 이스라엘 모든 사람과 더불어 세라의 아들 아간을 잡고 그 은과 그 외투와 그 금덩이와 그의 아들들과 그의 딸들과 그의 소들과 그의 나귀들과 그의 양들과 그의 장막과 그에게 속한 모든 것을 이끌고 아골 골짜기로 가서',6001),
('jos-7-25','jos','여호수아',7,25,'여호수아가 이르되 네가 어찌하여 우리를 괴롭게 하였느냐 여호와께서 오늘 너를 괴롭게 하시리라 하니 온 이스라엘이 그를 돌로 치고 물건들도 돌로 치고 불사르고',6002),
('jos-7-26','jos','여호수아',7,26,'그 위에 돌 무더기를 크게 쌓았더니 오늘까지 있더라 여호와께서 그의 맹렬한 진노를 그치시니 그러므로 그 곳 이름을 오늘까지 아골 골짜기라 부르더라',6003),
('jos-8-1','jos','여호수아',8,1,'여호와께서 여호수아에게 이르시되 두려워하지 말라 놀라지 말라 군사를 다 거느리고 일어나 아이로 올라가라 보라 내가 아이 왕과 그의 백성과 그의 성읍과 그의 땅을 다 네 손에 넘겨 주었으니',6004),
('jos-8-2','jos','여호수아',8,2,'너는 여리고와 그 왕에게 행한 것 같이 아이와 그 왕에게 행하되 오직 거기서 탈취할 물건과 가축은 스스로 가지라 너는 아이 성 뒤에 복병을 둘지니라 하시니',6005),
('jos-8-3','jos','여호수아',8,3,'이에 여호수아가 일어나서 군사와 함께 아이로 올라가려 하여 용사 삼만 명을 뽑아 밤에 보내며',6006),
('jos-8-4','jos','여호수아',8,4,'그들에게 명령하여 이르되 너희는 성읍 뒤로 가서 성읍을 향하여 매복하되 그 성읍에서 너무 멀리 하지 말고 다 스스로 준비하라',6007),
('jos-8-5','jos','여호수아',8,5,'나와 나를 따르는 모든 백성은 다 성읍으로 가까이 가리니 그들이 처음과 같이 우리에게로 쳐 올라올 것이라 그리 할 때에 우리가 그들 앞에서 도망하면',6008),
('jos-8-6','jos','여호수아',8,6,'그들이 나와서 우리를 추격하며 이르기를 그들이 처음과 같이 우리 앞에서 도망한다 하고 우리의 유인을 받아 그 성읍에서 멀리 떠날 것이라 우리가 그들 앞에서 도망하거든',6009),
('jos-8-7','jos','여호수아',8,7,'너희는 매복한 곳에서 일어나 그 성읍을 점령하라 너희 하나님 여호와께서 그 성읍을 너희 손에 주시리라',6010),
('jos-8-8','jos','여호수아',8,8,'너희가 그 성읍을 취하거든 그것을 불살라 여호와의 말씀대로 행하라 보라 내가 너희에게 명령하였느니라 하고',6011),
('jos-8-9','jos','여호수아',8,9,'그들을 보내매 그들이 매복할 곳으로 가서 아이 서쪽 벧엘과 아이 사이에 매복하였고 여호수아는 그 밤에 백성 가운데에서 잤더라',6012),
('jos-8-10','jos','여호수아',8,10,'여호수아가 아침에 일찍이 일어나 백성을 점호하고 이스라엘 장로들과 더불어 백성에 앞서 아이로 올라가매',6013),
('jos-8-11','jos','여호수아',8,11,'그와 함께 한 군사가 다 올라가서 그 성읍 앞에 가까이 이르러 아이 북쪽에 진 치니 그와 아이 사이에는 한 골짜기가 있더라',6014),
('jos-8-12','jos','여호수아',8,12,'그가 약 오천 명을 택하여 성읍 서쪽 벧엘과 아이 사이에 매복시키니',6015),
('jos-8-13','jos','여호수아',8,13,'이와 같이 성읍 북쪽에는 온 군대가 있고 성읍 서쪽에는 복병이 있었더라 여호수아가 그 밤에 골짜기 가운데로 들어가니',6016),
('jos-8-14','jos','여호수아',8,14,'아이 왕이 이를 보고 그 성읍 백성과 함께 일찍이 일어나 급히 나가 아라바 앞에 이르러 정한 때에 이스라엘과 싸우려 하나 성읍 뒤에 복병이 있는 줄은 알지 못하였더라',6017),
('jos-8-15','jos','여호수아',8,15,'여호수아와 온 이스라엘이 그들 앞에서 거짓으로 패한 척하여 광야 길로 도망하매',6018),
('jos-8-16','jos','여호수아',8,16,'그 성읍에 있는 모든 백성이 그들을 추격하려고 모여 여호수아를 추격하며 유인함을 받아 아이 성읍을 멀리 떠나니',6019),
('jos-8-17','jos','여호수아',8,17,'아이와 벧엘에 이스라엘을 따라가지 아니한 자가 하나도 없으며 성문을 열어 놓고 이스라엘을 추격하였더라',6020),
('jos-8-18','jos','여호수아',8,18,'여호와께서 여호수아에게 이르시되 네 손에 잡은 단창을 들어 아이를 가리키라 내가 이 성읍을 네 손에 넘겨 주리라 여호수아가 그의 손에 잡은 단창을 들어 그 성읍을 가리키니',6021),
('jos-8-19','jos','여호수아',8,19,'그의 손을 드는 순간에 복병이 그들의 자리에서 급히 일어나 성읍으로 달려 들어가서 점령하고 곧 성읍에 불을 놓았더라',6022),
('jos-8-20','jos','여호수아',8,20,'아이 사람이 뒤를 돌아본즉 그 성읍에 연기가 하늘에 닿은 것이 보이니 이 길로도 저 길로도 도망할 수 없이 되었고 광야로 도망하던 이스라엘 백성은 그 추격하던 자에게로 돌아섰더라',6023),
('jos-8-21','jos','여호수아',8,21,'여호수아와 온 이스라엘이 그 복병이 성읍을 점령함과 성읍에 연기가 오름을 보고 다시 돌이켜 아이 사람들을 쳐죽이고',6024),
('jos-8-22','jos','여호수아',8,22,'복병도 성읍에서 나와 그들을 치매 그들이 이스라엘 중간에 든지라 어떤 사람들은 이쪽에서 어떤 사람들은 저쪽에서 쳐죽여서 한 사람도 남거나 도망하지 못하게 하였고',6025),
('jos-8-23','jos','여호수아',8,23,'아이 왕을 사로잡아 여호수아 앞으로 끌어 왔더라',6026),
('jos-8-24','jos','여호수아',8,24,'이스라엘이 자기들을 광야로 추격하던 모든 아이 주민을 들에서 죽이되 그들을 다 칼날에 엎드러지게 하여 진멸하기를 마치고 온 이스라엘이 아이로 돌아와서 칼날로 죽이매',6027),
('jos-8-25','jos','여호수아',8,25,'그 날에 엎드러진 아이 사람들은 남녀가 모두 만 이천 명이라',6028),
('jos-8-26','jos','여호수아',8,26,'아이 주민들을 진멸하여 바치기까지 여호수아가 단창을 잡아 든 손을 거두지 아니하였고',6029),
('jos-8-27','jos','여호수아',8,27,'오직 그 성읍의 가축과 노략한 것은 여호와께서 여호수아에게 명령하신 대로 이스라엘이 탈취하였더라',6030),
('jos-8-28','jos','여호수아',8,28,'이에 여호수아가 아이를 불살라 그것으로 영원한 무더기를 만들었더니 오늘까지 황폐하였으며',6031),
('jos-8-29','jos','여호수아',8,29,'그가 또 아이 왕을 저녁 때까지 나무에 달았다가 해 질 때에 명령하여 그의 시체를 나무에서 내려 그 성문 어귀에 던지고 그 위에 돌로 큰 무더기를 쌓았더니 그것이 오늘까지 있더라',6032),
('jos-8-30','jos','여호수아',8,30,'그 때에 여호수아가 이스라엘의 하나님 여호와를 위하여 에발 산에 한 제단을 쌓았으니',6033),
('jos-8-31','jos','여호수아',8,31,'이는 여호와의 종 모세가 이스라엘 자손에게 명령한 것과 모세의 율법책에 기록된 대로 쇠 연장으로 다듬지 아니한 새 돌로 만든 제단이라 무리가 여호와께 번제물과 화목제물을 그 위에 드렸으며',6034),
('jos-8-32','jos','여호수아',8,32,'여호수아가 거기서 모세가 기록한 율법을 이스라엘 자손의 목전에서 그 돌에 기록하매',6035),
('jos-8-33','jos','여호수아',8,33,'온 이스라엘과 그 장로들과 관리들과 재판장들과 본토인뿐 아니라 이방인까지 여호와의 언약궤를 멘 레위 사람 제사장들 앞에서 궤의 좌우에 서되 절반은 그리심 산 앞에, 절반은 에발 산 앞에 섰으니 이는 전에 여호와의 종 모세가 이스라엘 백성에게 축복하라고 명령한 대로 함이라',6036),
('jos-8-34','jos','여호수아',8,34,'그 후에 여호수아가 율법책에 기록된 모든 것 대로 축복과 저주하는 율법의 모든 말씀을 낭독하였으니',6037),
('jos-8-35','jos','여호수아',8,35,'모세가 명령한 것은 여호수아가 이스라엘 온 회중과 여자들과 아이와 그들 중에 동행하는 거류민들 앞에서 낭독하지 아니한 말이 하나도 없었더라',6038),
('jos-9-1','jos','여호수아',9,1,'이 일 후에 요단 서쪽 산지와 평지와 레바논 앞 대해 연안에 있는 헷 사람과 아모리 사람과 가나안 사람과 브리스 사람과 히위 사람과 여부스 사람의 모든 왕들이 이 일을 듣고',6039),
('jos-9-2','jos','여호수아',9,2,'모여서 일심으로 여호수아와 이스라엘에 맞서서 싸우려 하더라',6040),
('jos-9-3','jos','여호수아',9,3,'기브온 주민들이 여호수아가 여리고와 아이에 행한 일을 듣고',6041),
('jos-9-4','jos','여호수아',9,4,'꾀를 내어 사신의 모양을 꾸미되 해어진 전대와 해어지고 찢어져서 기운 가죽 포도주 부대를 나귀에 싣고',6042),
('jos-9-5','jos','여호수아',9,5,'그 발에는 낡아서 기운 신을 신고 낡은 옷을 입고 다 마르고 곰팡이가 난 떡을 준비하고',6043),
('jos-9-6','jos','여호수아',9,6,'그들이 길갈 진영으로 가서 여호수아에게 이르러 그와 이스라엘 사람들에게 이르되 우리는 먼 나라에서 왔나이다 이제 우리와 조약을 맺읍시다 하니',6044),
('jos-9-7','jos','여호수아',9,7,'이스라엘 사람들이 히위 사람에게 이르되 너희가 우리 가운데에 거주하는 듯하니 우리가 어떻게 너희와 조약을 맺을 수 있으랴 하나',6045),
('jos-9-8','jos','여호수아',9,8,'그들이 여호수아에게 이르되 우리는 당신의 종들이니이다 하매 여호수아가 그들에게 묻되 너희는 누구며 어디서 왔느냐 하니',6046),
('jos-9-9','jos','여호수아',9,9,'그들이 여호수아에게 대답하되 종들은 당신의 하나님 여호와의 이름으로 말미암아 심히 먼 나라에서 왔사오니 이는 우리가 그의 소문과 그가 애굽에서 행하신 모든 일을 들으며',6047),
('jos-9-10','jos','여호수아',9,10,'또 그가 요단 동쪽에 있는 아모리 사람의 두 왕들 곧 헤스본 왕 시혼과 아스다롯에 있는 바산 왕 옥에게 행하신 모든 일을 들었음이니이다',6048),
('jos-9-11','jos','여호수아',9,11,'그러므로 우리 장로들과 우리 나라의 모든 주민이 우리에게 말하여 이르되 너희는 여행할 양식을 손에 가지고 가서 그들을 만나서 그들에게 이르기를 우리는 당신들의 종들이니 이제 우리와 조약을 맺읍시다 하라 하였나이다',6049),
('jos-9-12','jos','여호수아',9,12,'우리의 이 떡은 우리가 당신들에게로 오려고 떠나던 날에 우리들의 집에서 아직도 뜨거운 것을 양식으로 가지고 왔으나 보소서 이제 말랐고 곰팡이가 났으며',6050),
('jos-9-13','jos','여호수아',9,13,'또 우리가 포도주를 담은 이 가죽 부대도 새 것이었으나 찢어지게 되었으며 우리의 이 옷과 신도 여행이 매우 길었으므로 낡아졌나이다 한지라',6051),
('jos-9-14','jos','여호수아',9,14,'무리가 그들의 양식을 취하고는 어떻게 할지를 여호와께 묻지 아니하고',6052),
('jos-9-15','jos','여호수아',9,15,'여호수아가 곧 그들과 화친하여 그들을 살리리라는 조약을 맺고 회중 족장들이 그들에게 맹세하였더라',6053),
('jos-9-16','jos','여호수아',9,16,'그들과 조약을 맺은 후 사흘이 지나서야 그들이 이웃에서 자기들 중에 거주하는 자들이라 함을 들으니라',6054),
('jos-9-17','jos','여호수아',9,17,'이스라엘 자손이 행군하여 셋째 날에 그들의 여러 성읍들에 이르렀으니 그들의 성읍들은 기브온과 그비라와 브에롯과 기럇여아림이라',6055),
('jos-9-18','jos','여호수아',9,18,'그러나 회중 족장들이 이스라엘의 하나님 여호와로 그들에게 맹세했기 때문에 이스라엘 자손이 그들을 치지 못한지라 그러므로 회중이 다 족장들을 원망하니',6056),
('jos-9-19','jos','여호수아',9,19,'모든 족장이 온 회중에게 이르되 우리가 이스라엘의 하나님 여호와로 그들에게 맹세하였은즉 이제 그들을 건드리지 못하리라',6057),
('jos-9-20','jos','여호수아',9,20,'우리가 그들에게 맹세한 맹약으로 말미암아 진노가 우리에게 임할까 하노니 이렇게 행하여 그들을 살리리라 하고',6058),
('jos-9-21','jos','여호수아',9,21,'무리에게 이르되 그들을 살리라 하니 족장들이 그들에게 이른 대로 그들이 온 회중을 위하여 나무를 패며 물을 긷는 자가 되었더라',6059),
('jos-9-22','jos','여호수아',9,22,'여호수아가 그들을 불러다가 말하여 이르되 너희가 우리 가운데에 거주하면서 어찌하여 심히 먼 곳에서 왔다고 하여 우리를 속였느냐',6060),
('jos-9-23','jos','여호수아',9,23,'그러므로 너희가 저주를 받나니 너희가 대를 이어 종이 되어 다 내 하나님의 집을 위하여 나무를 패며 물을 긷는 자가 되리라 하니',6061),
('jos-9-24','jos','여호수아',9,24,'그들이 여호수아에게 대답하여 이르되 당신의 하나님 여호와께서 그의 종 모세에게 명령하사 이 땅을 다 당신들에게 주고 이 땅의 모든 주민을 당신들 앞에서 멸하라 하신 것이 당신의 종들에게 분명히 들리므로 당신들로 말미암아 우리의 목숨을 잃을까 심히 두려워하여 이같이 하였나이다',6062),
('jos-9-25','jos','여호수아',9,25,'보소서 이제 우리가 당신의 손에 있으니 당신의 의향에 좋고 옳은 대로 우리에게 행하소서 한지라',6063),
('jos-9-26','jos','여호수아',9,26,'여호수아가 곧 그대로 그들에게 행하여 그들을 이스라엘 자손의 손에서 건져서 죽이지 못하게 하니라',6064),
('jos-9-27','jos','여호수아',9,27,'그 날에 여호수아가 그들을 여호와께서 택하신 곳에서 회중을 위하며 여호와의 제단을 위하여 나무를 패며 물을 긷는 자들로 삼았더니 오늘까지 이르니라',6065),
('jos-10-1','jos','여호수아',10,1,'그 때에 여호수아가 아이를 빼앗아 진멸하되 여리고와 그 왕에게 행한 것 같이 아이와 그 왕에게 행한 것과 또 기브온 주민이 이스라엘과 화친하여 그 중에 있다 함을 예루살렘 왕 아도니세덱이 듣고',6066),
('jos-10-2','jos','여호수아',10,2,'크게 두려워하였으니 이는 기브온은 왕도와 같은 큰 성임이요 아이보다 크고 그 사람들은 다 강함이라',6067),
('jos-10-3','jos','여호수아',10,3,'예루살렘 왕 아도니세덱이 헤브론 왕 호함과 야르뭇 왕 비람과 라기스 왕 야비아와 에글론 왕 드빌에게 보내어 이르되',6068),
('jos-10-4','jos','여호수아',10,4,'내게로 올라와 나를 도우라 우리가 기브온을 치자 이는 기브온이 여호수아와 이스라엘 자손과 더불어 화친하였음이니라 하매',6069),
('jos-10-5','jos','여호수아',10,5,'아모리 족속의 다섯 왕들 곧 예루살렘 왕과 헤브론 왕과 야르뭇 왕과 라기스 왕과 에글론 왕이 함께 모여 자기들의 모든 군대를 거느리고 올라와 기브온에 대진하고 싸우니라',6070),
('jos-10-6','jos','여호수아',10,6,'기브온 사람들이 길갈 진영에 사람을 보내어 여호수아에게 전하되 당신의 종들 돕기를 더디게 하지 마시고 속히 우리에게 올라와 우리를 구하소서 산지에 거주하는 아모리 사람의 왕들이 다 모여 우리를 치나이다 하매',6071),
('jos-10-7','jos','여호수아',10,7,'여호수아가 모든 군사와 용사와 더불어 길갈에서 올라가니라',6072),
